public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a set to store the visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // Add the starting n-tersection to the visited set
    visited.add(start[0]);

    // Create a queue to store the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Get the paths from the current n-tersection to its adjacent n-tersections
        for (int[] path : paths) {
            // If the current n-tersection is the starting point of the path and the adjacent n-tersection is not in the visited set, add it to the visited set and add it to the queue
            if (current[0] == path[0] && !visited.contains(path[1])) {
                visited.add(path[1]);
                queue.add(new int[] {path[1], current[1]});
            }
        }
    }

    // If the queue is empty but the ending n-tersection is not in the visited set, return "cannot be travelled"
    if (!visited.contains(end[0])) {
        return "cannot be travelled";
    }

    // If the queue is empty and the ending n-tersection is in the visited set, return "can be travelled"
    return "can be travelled";
}

