public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] dateSplit = date.split(" ");
    int month = Integer.parseInt(dateSplit[0]);
    int day = Integer.parseInt(dateSplit[1]);
    int year = Integer.parseInt(dateSplit[2]);
    // Calculate the day of the week using the Zeller's congruence algorithm
    int century = year / 100;
    int yearOfTheCentury = year % 100;
    int dayOfTheWeek = (century / 4) - 2 * century + ((5 * yearOfTheCentury) / 4) + ((26 * (month + 1)) / 10) + day - 1;
    dayOfTheWeek = dayOfTheWeek % 7;
    // Return the formatted weekday
    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfTheWeek];
}

