    // Extract the month, day, and year from the input date
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Create a LocalDate object from the input date
    LocalDate localDate = LocalDate.of(year, month, day);

    // Get the weekday from the LocalDate object
    String weekday = localDate.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH);

    // Return the weekday of the date
    return String.format("%s is a %s", localDate.format(DateTimeFormatter.ofPattern("MMMM dd, yyyy")), weekday);
}

