public double trimMean(int[] arr) {
    double[] sortedArr = Arrays.stream(arr).sorted().toArray();

    // Find the smallest 5% and largest 5% of the elements and their indices
    int smallestPercentileIndex = (int) (arr.length * 0.05);
    int largestPercentileIndex = (int) (arr.length * 0.95);
    int smallestIndex = smallestPercentileIndex == arr.length ? arr.length - 1 : smallestPercentileIndex;
    int largestIndex = largestPercentileIndex == arr.length ? arr.length - 1 : largestPercentileIndex;

    // Calculate the mean of the remaining elements
    double sum = 0;
    for (int i = smallestIndex + 1; i < largestIndex; i++) {
        sum += sortedArr[i];
    }
    return sum / (largestIndex - smallestIndex - 1);
}

