    List<Integer> result = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        boolean isSteppingNumber = true;
        int prevDigit = Integer.MAX_VALUE;
        while (i > 0) {
            int currDigit = i % 10;
            if (currDigit == prevDigit) {
                isSteppingNumber = false;
                break;
            }
            int diff = currDigit - prevDigit;
            if (diff != 1 && diff != -1) {
                isSteppingNumber = false;
                break;
            }
            prevDigit = currDigit;
            i /= 10;
        }
        if (isSteppingNumber) {
            result.add(i);
        }
    }
    return result;
}

