    // Find the length of the string
    int len = str.length();

    // Sort the string in ascending order
    char[] chars = str.toCharArray();
    Arrays.sort(chars);

    // Create a new string from the sorted characters
    str = new String(chars);

    // Reverse the string
    String revStr = new StringBuffer(str).reverse().toString();

    // If the reversed string is greater than the original string, return the reversed string
    if (revStr.compareTo(str) > 0) {
        return Integer.parseInt(revStr);
    } else {
        // Otherwise, find the smallest number that is greater than the original number
        // by incrementing the last digit of the string
        int lastDigit = len - 1;
        chars[lastDigit] = (char) (chars[lastDigit] + 1);
        str = new String(chars);
        return Integer.parseInt(str);
    }
}

